from typing import List
from itertools import accumulate

def maxIncreasingGroups(usageLimits: List[int]) -> int:
    usageLimits.sort()
    n = len(usageLimits)

    def poss(groups):
        sub = [usageLimits[0]]
        for i in range(1, n):
            sub.append(usageLimits[i] - 1)

        for i in range(groups):
            sub[i] -= 1

        for i in accumulate(accumulate(sub)):
            if i < 0:
                return False
        return True

    l, r = 0, n
    while l < r:
        mid = (l + r + 1) // 2
        if poss(mid):
            l = mid
        else:
            r = mid - 1

    return l
